import json
import os
import pwd
from pathlib import Path

def _apply_owner(path, uid, mode):
    os.chown(path, uid, -1)
    os.chmod(path, mode)

def restrict_folder_to_owner(folder: str, username: str) -> dict:
    root = Path(folder).resolve()
    if not root.is_dir():
        return {'ok': False, 'error': 'folder not found'}
    # Read any earlier manifest to record who owned the folder previously
    prior_owner = None
    prior_path = root / '.access_manifest.json'
    if prior_path.exists():
        try:
            prior_owner = json.loads(prior_path.read_text()).get('owner')
        except ValueError:
            prior_owner = None
    uid = pwd.getpwnam(username).pw_uid
    changed = []
    _apply_owner(root, uid, 448)
    for item in root.rglob('*'):
        if item.is_symlink():
            continue
        mode = 448 if item.is_dir() else 384
        _apply_owner(item, uid, mode)
        changed.append(str(item.relative_to(root)))
    manifest = root / '.access_manifest.json'
    manifest.write_text(json.dumps({'owner': username, 'previous_owner': prior_owner, 'files': changed}, indent=2))
    _apply_owner(manifest, uid, 384)
    return {'ok': True, 'owner': username, 'count': len(changed), 'manifest': str(manifest)}
